role.apply:
if let Some(role) = crate::role::role_override($v) {
            element = element.$m(role);
        }

tooltip_with_action.apply:
{
            let name = $v;
            if !name.is_empty() {
                if let Some(action) = cx.app().and_then(|app| app.build_action(name, None).ok()) {
                    let context = props.tooltip_action_context();
                    element = element.$m(props.tooltip().to_string(), &*action, (!context.is_empty()).then_some(context));
                }
            }
        }

custom.apply:
if let Some(color) = $v {
            if let Some(app) = cx.app() {
                let mut variant = gpui_component::button::ButtonCustomVariant::new(app).color(crate::color::hsla(color));
                if let Some(c) = props.custom_foreground() { variant = variant.foreground(crate::color::hsla(c)); }
                if let Some(c) = props.custom_hover() { variant = variant.hover(crate::color::hsla(c)); }
                if let Some(c) = props.custom_active() { variant = variant.active(crate::color::hsla(c)); }
                if props.custom_shadow() { variant = variant.shadow(true); }
                element = element.$m(variant);
            }
        }

set_selection_focus.$raw:
let (Some(state), Some(handle)) = (self.state.clone(), self.selection_focus.clone()) else { return };
        cx.with_window(|window, app| {
            if hold {
                window.focus(&handle, app);
            } else if handle.is_focused(window) {
                state.update(app, |state, cx| state.focus(window, cx));
            }
        });

role.apply:
if let Some(role) = crate::role::role_override($v) {
            element = element.$m(role);
        }

on_paste.apply:
if $v {
            let sender = sender.clone();
            element = element.$m(move |item, _, _| {
                sender.gpui_kit_input_paste(OnGpuiKitInputPaste { text: item.text().unwrap_or_default() });
                false
            });
        }

on_token_click.apply:
if $v {
            let sender = sender.clone();
            element = element.$m(move |event, _, _| {
                let range = event.range();
                sender.gpui_kit_input_token_click(OnGpuiKitInputTokenClick { id: event.token().id().to_string(), start: range.start as i32, end: range.end as i32 });
            });
        }

on_token_hover.apply:
if $v {
            let sender = sender.clone();
            element = element.$m(move |event, _, _| {
                sender.gpui_kit_input_token_hover(OnGpuiKitInputTokenHover { id: event.token().id().to_string(), hovered: event.is_hovered() });
            });
        }

context_menu.apply:
{
            let items: Vec<(String, String, bool)> = { let list = $v; (0..list.len()).filter_map(|i| list.get(i)).map(|item| (item.label().to_string(), item.action().to_string(), item.disabled())).collect() };
            if !items.is_empty() {
                element = element.$m(move |mut menu, _, app| {
                    for (label, action, disabled) in &items {
                        if label == "-" {
                            menu = menu.separator();
                        } else if let Ok(action) = app.build_action(action, None) {
                            menu = menu.menu_with_disabled(label.clone(), *disabled, action);
                        }
                    }
                    menu
                });
            }
        }

token.apply:
if $v {
            let renderers = Rc::new(crate::manual::slots::Renderers::new(props.slots()));
            let sender = sender.clone();
            element = element.$m(move |context, window, cx| {
                let id = context.token().id().to_string();
                match renderers.get(&format!("token:{id}")) {
                    Some(render) => render(window, cx),
                    None => {
                        sender.gpui_kit_input_token_needed(OnGpuiKitInputTokenNeeded { id });
                        gpui_component::input::InputToken::new(context).into_any_element()
                    }
                }
            });
        }

rustBeforeReturn:
if self.selection_focus.is_none() {
            let handle = app.focus_handle();
            state.update(app, |state, cx| state.set_selection_focus(Some(handle.clone()), cx));
            self.selection_focus = Some(handle);
        }
        let held = self.selection_focus.as_ref().is_some_and(|handle| handle.is_focused(window));
        if held != self.selection_held {
            self.selection_held = held;
            sender.gpui_kit_input_selection_hold_change(OnGpuiKitInputSelectionHoldChange { held });
        }

highlights.apply:
{
            let text = $v;
            if !text.is_empty() {
                let text = SharedString::from(text.to_string());
                element = element.$m(if props.highlights_prefix() { gpui_component::label::HighlightsMatch::Prefix(text) } else { gpui_component::label::HighlightsMatch::Full(text) });
            }
        }

rotate.apply:
if $v != 0.0 && props.scale() == 1.0 {
            element = element.$m(gpui::radians(($v as f32).to_radians()));
        }

transform.apply:
if $v != 1.0 {
            element = element.$m(gpui::Transformation::rotate(gpui::radians((props.rotate() as f32).to_radians())).with_scaling(gpui::size($v as f32, $v as f32)));
        }

ease.apply:
match $v {
            GpuiKitSpinnerEasing::Linear => element = element.$m(gpui::linear),
            GpuiKitSpinnerEasing::Quadratic => element = element.$m(gpui::quadratic),
            GpuiKitSpinnerEasing::EaseOutQuint => element = element.$m(gpui::ease_out_quint()),
            _ => {}
        }

spread.apply:
if props.spread_pixels() > 0.0 {
            element = element.$m(gpui::px(props.spread_pixels() as f32));
        } else if $v > 0.0 {
            element = element.$m($v as f32);
        }

